import re
import urllib.request
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(API_URL):
    """
    Get the public IP address of the current host from an API.

    Args:
        API_URL (str): The URL of the API to fetch the public IP from.

    Returns:
        str: The public IP address.

    Raises:
        Exception: If the API request fails or the response does not contain a valid IP address.
    """
    try:
        # Make the API request
        with urllib.request.urlopen(API_URL) as response:
            data = response.read().decode('utf-8')

        # Try to parse as JSON first
        try:
            json_data = json.loads(data)
            # Look for IP in JSON structure (common keys)
            ip_candidates = []
            if isinstance(json_data, dict):
                for key in ['ip', 'IP', 'address', 'Address']:
                    if key in json_data:
                        ip_candidates.append(str(json_data[key]))
            elif isinstance(json_data, str):
                ip_candidates.append(json_data)

            # Check candidates for valid IP
            for candidate in ip_candidates:
                if re.fullmatch(IP_REGEX, candidate):
                    return candidate
        except json.JSONDecodeError:
            # If not JSON, try to extract IP from plain text
            match = re.search(IP_REGEX, data)
            if match:
                return match.group()

        # If we get here, no valid IP was found
        raise Exception("No valid IP address found in API response")

    except urllib.error.URLError as e:
        raise Exception(f"API request failed: {str(e)}")
    except Exception as e:
        raise Exception(f"Error: {str(e)}")

