import json
import os
from glob import glob
def task_func(directory, string):
    """
    Search for a specific string within the JSON data of files in a given directory and its subdirectories.
    This function recursively scans the specified directory for JSON files, then checks each file to see if 
    the given string is present within the JSON data structure.
    Note that: The string search is case-sensitive and looks for a match within the structure of the JSON data, 
    not just as a substring in the file content. If the directory does not contain any JSON files or if no JSON 
    files contain the string, an empty list is returned.

    Parameters:
    - directory (str): The path to the directory to search.
    - string (str): The string to search for in the JSON data.

    Returns:
    - list: A list of file paths (str) containing the string within their JSON data.
    """
    result_files = []

    # Recursively find all JSON files in directory and subdirectories
    json_files = glob(os.path.join(directory, '**', '*.json'), recursive=True)

    for file_path in json_files:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except (json.JSONDecodeError, UnicodeDecodeError, OSError):
            # Skip files that are not valid JSON or cannot be read
            continue

        # Recursively search for the string in the JSON data
        def search_in_json(obj):
            if isinstance(obj, str):
                return obj == string
            elif isinstance(obj, dict):
                for key, value in obj.items():
                    if key == string or search_in_json(value):
                        return True
            elif isinstance(obj, list):
                for item in obj:
                    if search_in_json(item):
                        return True
            return False

        if search_in_json(data):
            result_files.append(file_path)

    return result_files

