                    match = pattern.fullmatch(item)
                    if match:
                        try:
                            num = float(item)
                            new_list.append(num * 2)
                        except ValueError:
                            new_list.append(item)
                    else:
                        new_list.append(item)
                else:
                    new_list.append(item)
            normalized_data[key] = new_list
        elif isinstance(value, str):
            match = pattern.fullmatch(value)
            if match:
                try:
                    num = float(value)
                    normalized_data[key] = num * 2
                except ValueError:
                    normalized_data[key] = value
            else:
                normalized_data[key] = value
        else:
            normalized_data[key] = value

    try:
        df = pd.DataFrame(normalized_data)
    except Exception:
        df = pd.DataFrame()

    return df

