import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    """
    Process a JSON string by:
    1. Removing None values.
    2. Counting the frequency of each unique value.
    3. Replacing all email addresses with the placeholder "None".

    Parameters:
    - json_str (str): The JSON string to process.

    Returns:
    - dict: A dictionary containing:
        "data": Processed JSON data.
        "value_counts": A Counter object with the frequency of each unique value.

    Requirements:
    - json
    - re
    - collections.Counter
    """
    # Parse JSON string
    data = json.loads(json_str)

    # Helper function to process nested structures
    def process_item(item):
        if item is None:
            return None
        elif isinstance(item, dict):
            # Process dictionary recursively, removing None values
            new_dict = {}
            for key, value in item.items():
                processed_value = process_item(value)
                if processed_value is not None:
                    new_dict[key] = processed_value
            return new_dict if new_dict else None
        elif isinstance(item, list):
            # Process list recursively, removing None values
            new_list = []
            for value in item:
                processed_value = process_item(value)
                if processed_value is not None:
                    new_list.append(processed_value)
            return new_list if new_list else None
        elif isinstance(item, str):
            # Replace email addresses with placeholder
            email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
            if re.match(email_pattern, item):
                return REPLACE_NONE
            else:
                return item
        else:
            return item

    # Remove None values from the data
    processed_data = process_item(data)

    # Flatten the data to collect all values for counting
    def flatten(item):
        if isinstance(item, dict):
            for value in item.values():
                yield from flatten(value)
        elif isinstance(item, list):
            for value in item:
                yield from flatten(value)
        else:
            yield item

    # Count frequency of each unique value
    if processed_data is None:
        value_counts = Counter()
    else:
        value_counts = Counter(flatten(processed_data))

    return {
        "data": processed_data,
        "value_counts": value_counts
    }

