import numpy as np
from collections import defaultdict
import json
import csv
def task_func(input_file, output_file):
    """
    Read a list of dictionaries from a JSON file, calculate the mean and median for each key,
    and write the results to a CSV file.

    Parameters:
    - input_file (str): Path to the input JSON file.
    - output_file (str): Path to the output CSV file.

    Returns:
    - dict: A dictionary where each key is a field from the input JSON and each value is another 
            dictionary with the mean and median of that field.
    """
    try:
        # Read JSON data
        with open(input_file, 'r') as f:
            data = json.load(f)

        # Validate input data
        if not isinstance(data, list):
            raise ValueError("JSON data should be a list of dictionaries")

        # Collect all values by key
        values_by_key = defaultdict(list)
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("Each item in the list should be a dictionary")
            for key, value in item.items():
                # Only process numeric values
                if isinstance(value, (int, float)):
                    values_by_key[key].append(value)

        # Calculate statistics for each key
        result_dict = {}
        for key, values in values_by_key.items():
            if len(values) > 0:
                mean_val = np.mean(values)
                median_val = np.median(values)
                result_dict[key] = {
                    'mean': float(mean_val),
                    'median': float(median_val)
                }

        # Write results to CSV
        with open(output_file, 'w', newline='') as csvfile:
            fieldnames = ['key', 'mean', 'median']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

            writer.writeheader()
            for key, stats in result_dict.items():
                writer.writerow({
                    'key': key,
                    'mean': stats['mean'],
                    'median': stats['median']
                })

        return result_dict

    except FileNotFoundError:
        print(f"Error: Input file '{input_file}' not found.")
        return {}
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON format in '{input_file}'.")
        return {}
    except Exception as e:
        print(f"Error: {str(e)}")
        return {}

